#define MPU_ADDR 0x68   // AD0 pin wired to 3V3 on our board
#define WHO_AM_I 0x75

esp_err_t mpu_read_whoami(uint8_t *out) {
    uint8_t reg = WHO_AM_I;
    return i2c_master_write_read_device(I2C_NUM_0, MPU_ADDR, &reg, 1, out, 1,
                                        pdMS_TO_TICKS(100));
}
